func userPreferenceFromWire(w *userPreferenceWire) (*UserPreference, error) {
	if w == nil {
		return nil, nil
	}
	valueMembers := 0
	if w.BooleanVal != nil {
		valueMembers++
	}
	if w.StringVal != nil {
		valueMembers++
	}
	if valueMembers > 1 {
		return nil, fmt.Errorf("%s: multiple oneof members set", "UserPreference.Value")
	}
	effectiveValueMembers := 0
	if w.EffectiveBooleanVal != nil {
		effectiveValueMembers++
	}
	if w.EffectiveStringVal != nil {
		effectiveValueMembers++
	}
	if effectiveValueMembers > 1 {
		return nil, fmt.Errorf("%s: multiple oneof members set", "UserPreference.EffectiveValue")
	}
	var valueSelection isUserPreference_Value
	switch {
	case w.BooleanVal != nil:
		valueBooleanValConverted, err := booleanMessageFromWire(w.BooleanVal)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", "UserPreference.Value.BooleanVal", err)
		}
		valueSelection = &UserPreference_Value_BooleanVal{BooleanVal: *valueBooleanValConverted}
	case w.StringVal != nil:
		valueStringValConverted, err := stringMessageFromWire(w.StringVal)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", "UserPreference.Value.StringVal", err)
		}
		valueSelection = &UserPreference_Value_StringVal{StringVal: *valueStringValConverted}
	}
	var effectiveValueSelection isUserPreference_EffectiveValue
	switch {
	case w.EffectiveBooleanVal != nil:
		effectiveValueEffectiveBooleanValConverted, err := booleanMessageFromWire(w.EffectiveBooleanVal)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", "UserPreference.EffectiveValue.EffectiveBooleanVal", err)
		}
		effectiveValueSelection = &UserPreference_EffectiveValue_EffectiveBooleanVal{EffectiveBooleanVal: *effectiveValueEffectiveBooleanValConverted}
	case w.EffectiveStringVal != nil:
		effectiveValueEffectiveStringValConverted, err := stringMessageFromWire(w.EffectiveStringVal)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", "UserPreference.EffectiveValue.EffectiveStringVal", err)
		}
		effectiveValueSelection = &UserPreference_EffectiveValue_EffectiveStringVal{EffectiveStringVal: *effectiveValueEffectiveStringValConverted}
	}
	return &UserPreference{
		Name:           w.Name,
		UserId:         w.UserId,
		Value:          valueSelection,
		EffectiveValue: effectiveValueSelection,
	}, nil
}

func convertSlice[T, W any](s []T, conv func(*T) (*W, error)) ([]W, error) {
	if s == nil {
		return nil, nil
	}
	out := make([]W, len(s))
	for i := range s {
		converted, err := conv(&s[i])
		if err != nil {
			return nil, fmt.Errorf("element %d: %w", i, err)
		}
		out[i] = *converted
	}
	return out, nil
}
